custom_css:
/* =======================================================
🐍 Slytherin's Legacy & Serpensortia 🐍
💀 斯莱特林主题：纯血之傲 & 夜中密谋 💀
======================================================= */

/* ================/* ==========
   作者：Rinna@手机@2026-04-13@发布于个人群+DC社区欧皇锦鲤食堂&WBZ
   ========== */

/* ===== 说明书 =====
斯莱特林+HP+霍格沃兹之遗。FAN ART题材不开放二创。自改仅限聊天文字气泡内上下边距/字体/字号字重/正文颜色轻微改色（银白/白色范围内）/引用删除粗体斜体。其他均不可改动。Char聊天底部边距可自改以安放插件，有注释，请下拉查找
   =================== */

/* --- 1. 引入所有所需字体 --- */
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Jura:wght@500;600;700&family=Pinyon+Script&family=Cormorant+Garamond:ital,wght@1,500&display=swap');
@import url('https://cdn.jsdelivr.net/npm/lxgw-wenkai-webfont@1.1.0/style.css');

/* --- 2. 定义动画 --- */
@keyframes floatPostcard {
    0%, 100% { transform: rotate(-6deg) translateY(0); }
    50% { transform: rotate(-6deg) translateY(-8px); }
}

@keyframes twinkle {
    0%, 100% { opacity: 0.4; transform: scale(0.8) rotate(0deg); }
    50% { opacity: 1; transform: scale(1.3) rotate(45deg); }
}

@keyframes pulseGlowSlytherin {
    0%, 100% { filter: drop-shadow(0 0 8px rgba(129, 199, 132, 0.4)); transform: scale(1); }
    50% { filter: drop-shadow(0 0 15px rgba(76, 175, 80, 0.8)); transform: scale(1.05); }
}

body, html, #root, .popup {
    font-family: 'Cormorant Garamond', 'LXGW WenKai', serif !important;
}

h1, h2, h3, h4, h5, h6, 
.standoutHeader, 
.drawer-header,
#top-bar {
    font-family: 'Cinzel', 'LXGW WenKai', serif !important;
}

.mes_text, 
#send_textarea {
    font-family: 'Cormorant Garamond', 'LXGW WenKai', serif !important;
}

input, textarea, select {
    font-family: 'Cormorant Garamond', 'LXGW WenKai', serif !important;
}

.timestamp, .mesIDDisplay, .tokenCounterDisplay, .swipe_counter {
    font-family: 'Cormorant Garamond', 'LXGW WenKai', serif !important;
}

#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

#bg-header-fixed {
   background: rgba(220, 170, 180, 0.2) !important;   
    border-radius: 16px !important;
}

/* 底栏控制台 */
:root {
    --send-bottom-margin: 15px; 
    --send-icon-size: 26px;    
    --send-icon-gap: 10px;     
}

/* 顶栏：全透明 & 斯莱特林发光图标  */

/* 顶部栏无阴影 */
#top-bar {
  box-shadow: none !important;
}

/* 顶栏透明 */
body.no-blur #top-bar {
  background-color: transparent !important;
  box-shadow: none !important;
}

/* 顶栏图标替换感谢@美化楼@长大难道是人必经的溃烂  */
#top-settings-holder,
#top-settings-holder .drawer,
#top-settings-holder .drawer-toggle,
#top-settings-holder .drawer-header,
#top-bar {
  background-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 图标居中 */
#top-settings-holder > div {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 隐藏顶栏图标 */
#top-settings-holder > div >:first-child {
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
  background-size: 26px auto !important; 
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 40px !important;
  height: 40px !important;
  margin-top: 0 !important;
}

#top-settings-holder .drawer-icon::before,
#top-settings-holder .drawer-icon:hover::before,
#top-settings-holder .drawer-icon:not(.closedIcon)::before {
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 顶栏图标替换 */
#top-settings-holder > .drawer:nth-of-type(1) .drawer-toggle {
  background-image: url("https://i.ibb.co/0yDJ8r3x/Image-1775993324284-118.png") !important;
  transform: scale(1.1) !important;
}

/* 顶栏图标替换 */
#top-settings-holder > .drawer:nth-of-type(2) .drawer-toggle {
  background-image: url("https://i.ibb.co/sJNv6jfh/Image-1775993541712-285.png") !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(3) .drawer-toggle {
  background-image: url("https://i.ibb.co/tPDrYs8M/Image-1775993614087-981.png") !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(4) .drawer-toggle {
  background-image: url("https://i.ibb.co/fGKrqfNm/Image-1775993228737-574.png") !important;
}

#top-settings-holder > .drawer:nth-of-type(5) .drawer-toggle {
  background-image: url("https://i.ibb.co/gZSqRxRY/Image-1775992901044-785.png") !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(6) .drawer-toggle {
  background-image: url("https://i.ibb.co/bgfPtgSF/Image-1775993005762-22.png") !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(8) .drawer-toggle {
  background-image: url("https://i.ibb.co/5x5btgSL/Image-1775993695984-63.png") !important;
}

#top-settings-holder > .drawer:nth-of-type(7) .drawer-toggle {
  background-image: url("https://i.ibb.co/0jNvLb55/Image-1775993357155-197.png") !important;
}

#top-settings-holder > .drawer:nth-of-type(9) .drawer-toggle {
  background-image: url("https://i.ibb.co/hFRgcqjJ/Image-1775993453899-203.png") !important;
}

#top-settings-holder > .drawer:nth-of-type(10) .drawer-toggle {
  background-image: url("https://i.ibb.co/hFRgcqjJ/Image-1775993453899-203.png") !important;
  transform: scale(1.1) !important;
}

/* 顶栏图标悬停和选中 */
#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer:has(.drawer-content.openDrawer) .drawer-toggle {
  filter: drop-shadow(0 0 5px #81c784) drop-shadow(0 0 10px #2e7d32) !important;
}


/*  AI气泡下层文字 */

/* 1. 魔法呼吸光效 (AI专属) */
@keyframes darkArtifactBreath {
    0%, 100% { box-shadow: inset 0 0 30px rgba(76, 175, 80, 0.05), 0 5px 15px rgba(0,0,0,0.6); }
    50% { box-shadow: inset 0 0 40px rgba(129, 199, 132, 0.1), 0 8px 25px rgba(27, 94, 32, 0.5); }
}

/* 基础容器 */
.mes[is_user="false"] {
    position: relative !important;
    width: 96% !important;              
    max-width: 600px !important;         
    margin-left: auto !important;        
    margin-right: auto !important;
    margin-top: 320px !important;        
    margin-bottom: 40px !important;      
    box-sizing: border-box !important;
    padding: 40px 20px 45px 10px !important; 
    border-radius: 16px !important;
    border-top-left-radius: 4px !important;

    background: linear-gradient(135deg, rgba(15, 40, 20, 0.8), rgba(0, 0, 0, 0.85)) !important;
    border: 1px solid rgba(170, 200, 170, 0.3) !important; 
    border-top: 1px solid rgba(200, 230, 200, 0.5) !important;

    animation: darkArtifactBreath 6s infinite ease-in-out !important; 
    overflow: visible !important;
}

.mes[is_user="false"] .mes_block {
    overflow: visible !important;
    position: relative !important;
    z-index: 2 !important;
}

/* 信笺装饰 */
.mes[is_user="false"] .mes_block::before {
    content: 'Toujours Pur' !important;
    position: absolute !important;
    top: -65px !important; 
    left: 10px !important;
    font-family: 'Pinyon Script', cursive !important;
    font-size: 2.6em !important; 
    color: #e0f2f1 !important; 
    text-shadow: 
        0 0 6px rgba(255, 255, 255, 0.9),
        0 0 15px rgba(76, 175, 80, 0.9),
        0 0 25px rgba(27, 94, 32, 0.8),
        2px 2px 4px rgba(0, 0, 0, 0.8) !important;
    z-index: 20 !important;
    transform: rotate(-6deg) !important; 
    white-space: nowrap !important;
    pointer-events: none !important;
}

/* 信笺装饰：闪烁的银星 ✦ */
.mes[is_user="false"] .mes_text::before {
    content: '✦' !important;
    position: absolute !important;
    top: -65px !important;  
    left: 190px !important; 
    font-size: 12px !important;
    color: #e0f2f1 !important;
    text-shadow: 0 0 6px #fff, 0 0 15px #81c784 !important; 
    animation: twinkle 3s infinite ease-in-out !important;
    z-index: 25 !important;
    pointer-events: none !important;
}

/* 信笺装饰：底部落款文字 (野心与精明) */
.mes[is_user="false"] .mes_block::after {
    content: 'Ambitio, Astutia, Gloria' !important;
    position: absolute !important;
    bottom: -22px !important;
    right: 35px !important;
    font-family: 'Cormorant Garamond', serif !important;
    font-style: italic !important;
    font-size: 1em !important;
    color: #c8e6c9 !important;
    letter-spacing: 1px !important;
    text-shadow: 0 1px 3px rgba(0,0,0,0.8) !important;
    z-index: 10 !important;
}

/* 上层头像卡片 */

.mes[is_user="false"]::before {
    content: "" !important;
    position: absolute !important;
    top: -275px !important; 
    left: 5% !important;
    width: 94% !important;
    max-width: 240px !important;         
    height: 230px !important;
  background: rgba(10, 20, 15, 0.75) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border-radius: 6px !important;
  border-top: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-left: 1px solid rgba(255, 255, 255, 0.1) !important;
  box-shadow: 0 0 15px rgba(0, 255, 106, 0.15), inset 0 0 10px rgba(0, 0, 0, 0.5) !important;
    z-index: 1 !important;
    pointer-events: none !important;
}

/* 悬浮签名 (萨拉查的遗产) */
.mes[is_user="false"]::after {
    content: "Salazar's Legacy" !important;
    position: absolute !important;
    top: -85px !important; 
    right: -5px !important; 
    font-family: 'Pinyon Script', cursive !important;
    font-size: 2.5em !important;
    color: #e0f2f1 !important;
    white-space: nowrap !important;
    z-index: 20 !important;
    pointer-events: none !important;
    text-shadow: 0 0 4px #fff, 0 0 10px #4caf50, 0 0 20px #1b5e20 !important;
    animation: floatPostcard 5s ease-in-out infinite !important;
}

.mes[is_user="false"] .avatar {
    position: absolute !important;
    top: -230px !important; 
    left: 60px !important; 
    width: 240px !important;  
    height: 150px !important; 
    border-radius: 0 !important;
    background: linear-gradient(135deg, rgba(129,199,132,0.25), rgba(27,94,32,0.15)) !important;
    border: 2px solid #66bb6a !important;          
    box-shadow: 0 0 12px rgba(76, 175, 80, 0.7), inset 0 0 8px rgba(255,255,255,0.1) !important;
    padding: 3px !important;
    z-index: 10 !important;
}

/* 头像图片拉伸与裁剪 */
#chat .mes[is_user="false"] .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center 20% !important;  /* 从顶部开始裁 */
    border-radius: 0 !important;
}

/* 信息区与火漆印章排版 */

/* 回复 */
.mes[is_user="false"] .ch_name::before {
    content: "Response" !important;
    position: absolute !important;
    top: -300px !important;
    left: 20px !important;
    font-family: 'Pinyon Script', cursive !important;
    font-size: 12px !important;
    letter-spacing: 2px !important;
    color: #e0f2f1 !important;
    font-weight: 700 !important;
    text-shadow: 0 0 5px rgba(46, 125, 50, 0.9) !important;
    z-index: 5 !important;
}

/* 时间戳 */
.mes[is_user="false"] .timestamp {
    position: absolute !important;
    top: -302px !important;    
    left: 80px !important;     
    display: inline-block !important;
    font-family: 'Cormorant Garamond', serif !important;
    font-style: italic !important;
    font-size: 0.85em !important;
    color: #a5d6a7 !important;
    letter-spacing: 1px !important;
    opacity: 0.9 !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.8) !important;
    padding: 2px 6px !important;
    border-radius: 4px !important;
    z-index: 30 !important;    
    pointer-events: none !important;
}

/* 名字框 */
.mes[is_user="false"] .name_text {
  position: absolute !important;
  left: 280px !important;
  top: -315px !important;
  width: 65px !important;
  max-height: 230px !important;
  background: rgba(10, 20, 15, 0.75) !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  border-radius: 6px !important;
  border-top: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-left: 1px solid rgba(255, 255, 255, 0.1) !important;
  box-shadow: 0 0 15px rgba(0, 255, 106, 0.15), inset 0 0 10px rgba(0, 0, 0, 0.5) !important;
  padding: 10px 8px 8px 8px !important;
  writing-mode: vertical-rl !important;  
  text-orientation: mixed !important;    
  font-family: 'Cinzel', serif !important;
  font-size: 1.1em !important;
  color: #c8e6c9 !important;
  text-shadow: 0 0 5px rgba(76, 175, 80, 0.5) !important;
  line-height: 1.3 !important;
  letter-spacing: 2px !important;        
  word-break: break-word !important;
  white-space: normal !important;
  text-align: left !important;           
  z-index: 10 !important;
}

/* Index、Weight 基础样式 */
.mes[is_user="false"] .mesIDDisplay,
.mes[is_user="false"] .tokenCounterDisplay {
  position: absolute !important;
  background: transparent !important;
  border: none !important;
  left: 23px !important; 
  padding: 6px !important;
  color: #f0f0f0 !important;
  text-shadow: 0 0 8px rgba(76, 175, 80, 0.6) !important;
  z-index: 10 !important;
  text-align: left !important;
}

.mes[is_user="false"] .mesIDDisplay,
.mes[is_user="false"] .tokenCounterDisplay {
  width: calc(100% - 190px) !important;
}

.mes[is_user="false"] .mesIDDisplay { top: -140px !important; }
.mes[is_user="false"] .mesIDDisplay::before {
    content: "Index: " !important;
    font-family: 'Pinyon Script', cursive !important;
    font-size: 1.2em !important;
}

.mes[is_user="false"] .tokenCounterDisplay { top: -120px !important; }
.mes[is_user="false"] .tokenCounterDisplay::before {
    content: "Weight: " !important;
    font-family: 'Pinyon Script', cursive !important;
    font-size: 1.2em !important;
}

/* AI 正文与按钮排版 */
.mes[is_user="false"] .mes_timer,
.mes[is_user="false"] .mes_performance {
    position: absolute !important;
    float: none !important;    
    top: -30px !important;      
    left: 10px !important; 
    font-family: 'Jura', sans-serif !important;
    font-size: 11px !important;
    color: rgba(180, 220, 180, 0.5) !important;
    text-shadow: 0 0 5px rgba(27, 94, 32, 0.5) !important;
    background: transparent !important;
    border: none !important;
    z-index: 50 !important;
    pointer-events: none !important;
}

/* 底部距离不够的话改下面那个margin-bottom: 50px !important; 把50改大一点 */
.mes[is_user="false"] .mes_text {
    font-family: 'LXGW WenKai', 'Noto Sans SC', 'Jura', sans-serif !important;
    color: #e0f2f1 !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.8) !important;
    font-size: 0.95em !important;
    font-weight: 400 !important;  
    letter-spacing: 0.5px !important;
    line-height: 1.8 !important;
    text-align: justify !important;    
    margin-bottom: 50px !important; 
    padding-right: 0 !important;
    margin-right: 0 !important;
}

.mes[is_user="false"] .mes_buttons {
    position: absolute !important;
    top: -25px !important;
    right: 1px !important;
    z-index: 30 !important;
    background: rgba(10, 20, 15, 0.6) !important;
    border-radius: 20px !important;
    padding: 4px 10px !important;
    backdrop-filter: blur(4px) !important;
    display: flex !important;
    gap: 8px !important;
    opacity: 0.3 !important;
    transition: opacity 0.2s !important;
    font-size: 0.85em !important;
}
.mes[is_user="false"]:hover .mes_buttons { opacity: 1 !important; }

.mes[is_user="false"] .mes_edit_buttons {
    transform: scale(0.85) !important;   
    transform-origin: top right !important;  
}

/* 翻页按钮 /
.swipe_left, .swipe_right { font-size: 0 !important; }
.swipe_left::before { content: "§" !important; font-size: 16px !important; color: #a5d6a7 !important; }
.swipe_right::before { content: "§" !important; font-size: 16px !important; color: #a5d6a7 !important; }
.swipes-counter {
  font-family: 'Cormorant Garamond', serif !important;
  font-style: italic !important;
  font-size: 12px !important;
  color: #a5d6a7 !important;
}

/*  User 侧：星夜密谋气泡 (Slytherin Ally) */
.mes[is_user="true"] {
    position: relative !important;
    width: 92% !important;              
    max-width: 550px !important;         
    margin-left: auto !important;     
    margin-right: 15px !important;
    margin-top: 80px !important;      
    margin-bottom: 30px !important;      
    box-sizing: border-box !important;
    padding: 35px 20px 30px 20px !important;
    border-radius: 16px !important;
    border-top-right-radius: 2px !important; 
    background: linear-gradient(145deg, rgba(15, 20, 15, 0.75), rgba(5, 10, 5, 0.7)) !important;
    border: 1px solid rgba(129, 199, 132, 0.2) !important;
    border-top: 1px solid rgba(129, 199, 132, 0.4) !important;
    border-right: 1px solid rgba(129, 199, 132, 0.4) !important;
    box-shadow: inset 0 0 20px rgba(76, 175, 80, 0.05), 0 8px 20px rgba(0, 0, 0, 0.5) !important;
    overflow: visible !important;
}

.mes[is_user="true"] .mes_block {
    overflow: visible !important;
    position: relative !important;
    z-index: 2 !important;
}

.mes[is_user="true"] .mes_block::before {
    content: "Serpensortia" !important;
    position: absolute !important;
    top: -60px !important; 
    right: 70px !important; 
    font-family: 'Pinyon Script', cursive !important;
    font-size: 2.2em !important; 
    color: #e0f2f1 !important;
    text-shadow: 
        0 0 6px rgba(255, 255, 255, 0.8),
        0 0 15px rgba(76, 175, 80, 0.8),
        0 0 25px rgba(46, 125, 50, 0.7),
        2px 2px 4px rgba(0, 0, 0, 0.8) !important;      
    z-index: 20 !important;
    transform: rotate(3deg) !important;  
    white-space: nowrap !important;
    pointer-events: none !important;
}

/* 装饰 */
.mes[is_user="true"] .mes_block::after {
    content: ' § In nocte consilium' !important; 
    position: absolute !important;
    bottom: -20px !important;
    left: 30px !important; 
    font-family: 'Cormorant Garamond', serif !important;
    font-style: italic !important;
    font-size: 0.9em !important;
    color: #a5d6a7 !important;
    letter-spacing: 1px !important;
    opacity: 0.7 !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.8) !important;
    z-index: 10 !important;
}

/* User 头像 */
.mes[is_user="true"] .avatar {
    position: absolute !important;
    top: -45px !important;
    right: -10px !important; 
    width: 70px !important;
    height: 70px !important;
    border-radius: 50% !important; 
    background: linear-gradient(135deg, rgba(129,199,132,0.3), rgba(27,94,32,0.2)) !important;
    border: 2px solid rgba(170, 200, 170, 0.6) !important;
    padding: 3px !important;
    box-shadow: 0 0 15px rgba(46, 125, 50, 0.6), inset 0 0 10px rgba(255, 255, 255, 0.1) !important;
    z-index: 25 !important;
}
.mes[is_user="true"] .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
}

/* User 名字 */
.mes[is_user="true"] .ch_name {
    position: absolute !important;
    top: -25px !important;
    left: 15px !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
}
.mes[is_user="true"] .name_text {
    font-family: 'Cinzel', serif !important;
    font-size: 1.2em !important;
    color: rgba(200, 230, 200, 0.9) !important; 
    letter-spacing: 1.5px !important;
    text-shadow: 0 0 8px rgba(76, 175, 80, 0.6) !important;
}

/* 隐藏 User 侧多余信息 */
.mes[is_user="true"] .mesIDDisplay,
.mes[is_user="true"] .tokenCounterDisplay { display: none !important; }

.mes[is_user="true"] .timestamp {
    display: inline-block !important;
    font-family: 'Cormorant Garamond', serif !important;
    font-style: italic !important;
    font-size: 0.9em !important;
    color: #a5d6a7 !important;
    letter-spacing: 1px !important;
    opacity: 0.7 !important;
    text-shadow: 0 1px 2px rgba(0,0,0,0.8) !important;
}

/* User 侧计时器与按钮 */
.mes[is_user="true"] .mes_timer,
.mes[is_user="true"] .mes_performance {
