/* 魔法滑动条外层 */
.block:has(input[type=range]),
.flex-container:has(input[type=range]) {
    overflow: visible !important;
    border-radius: 0 !important;
    clip-path: none !important;
}

input[type=range] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: transparent !important;
    opacity: 1 !important;
    filter: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    overflow: visible !important;
    height: auto !important;
}

/* 滑块本 */
input[type=range]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    background: url("https://i.ibb.co/dwQQyPfm/Image-1775993410747-585.png") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    border-radius: 0 !important;
    height: 20px !important;
    width: 20px !important;
    margin-top: -6px !important;
    cursor: pointer !important;
    transition: transform 0.2s ease, filter 0.2s ease !important;
}

input[type=range]::-moz-range-thumb {
    background: url("https://i.ibb.co/dwQQyPfm/Image-1775993410747-585.png") !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    border: none !important;
    border-radius: 0 !important;
    height: 20px !important;
    width: 20px !important;
    margin-top: -6px !important;
    cursor: pointer !important;
    transition: transform 0.2s ease, filter 0.2s ease !important;
}

/* 滑块悬停 */
input[type=range]::-webkit-slider-thumb:hover {
    transform: scale(1.2) rotate(5deg) !important;
    filter: drop-shadow(0 0 6px rgba(46, 255, 148, 0.8)) !important;
}
input[type=range]::-moz-range-thumb:hover {
    transform: scale(1.2) rotate(5deg) !important;
    filter: drop-shadow(0 0 6px rgba(46, 255, 148, 0.8)) !important;
}

/* 滑动轨迹 */
input[type=range]::-webkit-slider-runnable-track {
    width: 100% !important;
    height: 3px !important; 
    background: linear-gradient(90deg, #1b3825, rgba(0, 255, 106, 0.8)) !important;
    border-radius: 4px !important;
    border: none !important;
    cursor: pointer !important;
    box-shadow: 0 0 4px rgba(0, 255, 106, 0.3), inset 0 1px 2px rgba(0,0,0,0.8) !important;
}

